import{_ as t,r as o,o as a,c as d,e as l,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Структура каталогов - October CMS - 3.x","titleTemplate":false,"description":"Узнайте назначение каждого каталога в корневой папке October CMS.","frontmatter":{"subtitle":"Узнайте назначение каждого каталога в корневой папке October CMS."},"headers":[{"level":2,"title":"Корневой каталог","slug":"корневои-каталог","link":"#корневои-каталог","children":[{"level":3,"title":"Каталог App","slug":"каталог-app","link":"#каталог-app","children":[]},{"level":3,"title":"Каталог Bootstrap","slug":"каталог-bootstrap","link":"#каталог-bootstrap","children":[]},{"level":3,"title":"Каталог Config","slug":"каталог-config","link":"#каталог-config","children":[]},{"level":3,"title":"Каталог Plugins","slug":"каталог-plugins","link":"#каталог-plugins","children":[]},{"level":3,"title":"Каталог Storage","slug":"каталог-storage","link":"#каталог-storage","children":[]},{"level":3,"title":"Каталог Modules","slug":"каталог-modules","link":"#каталог-modules","children":[]},{"level":3,"title":"Каталог Themes","slug":"каталог-themes","link":"#каталог-themes","children":[]},{"level":3,"title":"Каталог Vendor","slug":"каталог-vendor","link":"#каталог-vendor","children":[]}]},{"level":2,"title":"Каталог App","slug":"каталог-app-1","link":"#каталог-app-1","children":[{"level":3,"title":"Каталог Assets","slug":"каталог-assets","link":"#каталог-assets","children":[]},{"level":3,"title":"Каталог Blueprints","slug":"каталог-blueprints","link":"#каталог-blueprints","children":[]},{"level":3,"title":"Другие каталоги","slug":"другие-каталоги","link":"#другие-каталоги","children":[]}]}],"relativePath":"3.x/ru/setup/directory-structure.md","filePath":"3.x/ru/setup/directory-structure.md"}'),p={name:"3.x/ru/setup/directory-structure.md"};function n(h,e,u,m,g,f){const s=o("pre-heading"),r=o("post-heading");return a(),d("div",null,[l(s),e[0]||(e[0]=c("h1",null,"Структура каталогов",-1)),l(r),e[1]||(e[1]=i('<p>October CMS использует модульную структуру, в которой большинство программных функций находится в каталогах модулей или плагинов.</p><h2 id="корневои-каталог"><a href="#корневои-каталог" class="header-anchor">#</a> Корневой каталог</h2><h3 id="каталог-app"><a href="#каталог-app" class="header-anchor">#</a> Каталог App</h3><p>Каталог <code>app</code> содержит код, специфичный для приложения. Содержимое этого каталога подробнее рассматривается далее в этом разделе. В общих чертах, здесь располагается бизнес-логика, которая не относится к традиционным плагинам. Большинство возможностей плагинов доступно и в этом каталоге.</p><h3 id="каталог-bootstrap"><a href="#каталог-bootstrap" class="header-anchor">#</a> Каталог Bootstrap</h3><p>Каталог <code>bootstrap</code> содержит скрипт начальной загрузки app.php, который загружает фреймворк Laravel. В этом каталоге также находится пользовательский автозагрузчик PHP-классов. Как правило, файлы в этом каталоге не следует изменять.</p><h3 id="каталог-config"><a href="#каталог-config" class="header-anchor">#</a> Каталог Config</h3><p>Каталог <code>config</code> содержит все файлы конфигурации приложения. Каждый файл управляет определённым аспектом работы приложения. Файлы конфигурации можно изменять в соответствии с требованиями вашего приложения. Обновления системы не изменяют файлы конфигурации.</p><h3 id="каталог-plugins"><a href="#каталог-plugins" class="header-anchor">#</a> Каталог Plugins</h3><p>Каталог <code>plugins</code> содержит пакеты, расширяющие базовую функциональность October CMS. Плагины могут модифицировать платформу, добавляя новые возможности. По умолчанию система загружает все плагины, найденные в файловой системе. Определённые плагины можно отключить с помощью параметра конфигурации <code>system.disable_plugins</code>.</p><h3 id="каталог-storage"><a href="#каталог-storage" class="header-anchor">#</a> Каталог Storage</h3><p>Каталог <code>storage</code> содержит файлы журналов, файлы кэша, сессии и другие файлы, генерируемые October CMS. Он включает несколько подкаталогов:</p><ul><li><code>app</code> — содержит файлы хранилища, специфичные для приложения, такие как медиафайлы, загруженные файлы и автоматически генерируемые ресурсы, например, файлы изменённого размера и объединённые файлы ресурсов.</li><li><code>framework</code> — используется фреймворком Laravel для хранения сгенерированных файлов и кэшей.</li><li><code>cms</code> — используется платформой October CMS для хранения сгенерированных файлов и кэшей.</li><li><code>logs</code> — содержит файлы журналов приложения.</li><li><code>temp</code> — используется для хранения временных файлов приложения.</li></ul><h3 id="каталог-modules"><a href="#каталог-modules" class="header-anchor">#</a> Каталог Modules</h3><p>Каталог <code>modules</code> содержит основные пакеты October CMS, предоставляющие базовую функциональность, общую для всей системы. По умолчанию модули загружаются автоматически на основе их наличия в файловой системе. Однако можно указать, какие модули загружать, с помощью параметра конфигурации <code>system.load_modules</code>. Для работы приложения как минимум должен быть загружен модуль <code>system</code>.</p><ul><li><code>system</code> — определяет базовую функциональность October CMS и является обязательным модулем.</li><li><code>cms</code> — обеспечивает функциональность для отображения фронтенд-темы сайта. Отвечает за маршрутизацию запросов к страницам, отображение страниц и обработку AJAX-запросов.</li><li><code>backend</code> — отвечает за отображение страниц панели администрирования.</li><li><code>editor</code> — предоставляет пользовательский интерфейс для редактирования CMS-шаблонов в панели администрирования.</li><li><code>media</code> — предоставляет пользовательский интерфейс для управления медиафайлами в панели администрирования. Позволяет пользователям загружать медиафайлы, такие как изображения или видеофайлы, и использовать их в других местах, например, в записях блога.</li><li><code>tailor</code> — обеспечивает функциональность Tailor в October CMS.</li></ul><h3 id="каталог-themes"><a href="#каталог-themes" class="header-anchor">#</a> Каталог Themes</h3><p>Каталог <code>themes</code> содержит подкаталоги для фронтенд-тем CMS-сайта. Темы CMS включают файлы шаблонов для страниц сайта, макетов, фрагментов, ресурсов и других файлов. Активная тема задаётся с помощью параметра конфигурации <code>cms.active_theme</code> и может быть переопределена на странице настроек панели администрирования.</p><h3 id="каталог-vendor"><a href="#каталог-vendor" class="header-anchor">#</a> Каталог Vendor</h3><p>Каталог <code>vendor</code> содержит пакеты, подключённые через Composer. Некоторые плагины также могут включать каталог vendor. Системный каталог vendor имеет приоритет над каталогами vendor отдельных плагинов.</p><h2 id="каталог-app-1"><a href="#каталог-app-1" class="header-anchor">#</a> Каталог App</h2><p>Каталог <code>app</code> содержит файлы, специфичные для приложения, включая контент, ресурсы и бизнес-логику, которая не относится к <a href="./../extend/system/plugins.html">традиционным плагинам</a>. Он включает файл сервис-провайдера, загружаемый конфигурацией по умолчанию.</p><h3 id="каталог-assets"><a href="#каталог-assets" class="header-anchor">#</a> Каталог Assets</h3><p>Каталог <code>app/assets</code> содержит файлы ресурсов, такие как JavaScript, CSS и файлы изображений. Этот каталог должен быть публично доступен для сайта.</p><h3 id="каталог-blueprints"><a href="#каталог-blueprints" class="header-anchor">#</a> Каталог Blueprints</h3><p>Каталог <code>app/blueprints</code> содержит файлы <a href="./../cms/tailor/introduction.html">схем контента</a>, используемые Tailor.</p><h3 id="другие-каталоги"><a href="#другие-каталоги" class="header-anchor">#</a> Другие каталоги</h3><p>Вы можете создавать любые каталоги внутри этой директории, как и в плагине, например <code>models</code> или <code>controllers</code>. Они будут автоматически загружены в пространстве имён <code>App</code>. Например, файл <strong>app/models/Customer.php</strong> будет доступен в PHP как <code>App\\Models\\Customer</code>.</p>',28))])}const S=t(p,[["render",n]]);export{_ as __pageData,S as default};
